cd /tmp/probe && python3 - <<'EOF'
import json
def load(t):
    d = json.load(open(f'map_{t}.json'))
    w,h = d['w'], d['h']
    return w,h,[d['prod'][y*w+x] for y in range(h) for x in range(w)],[d['strs'][y*w+x] for y in range(h) for x in range(w)]
for t in ['n3_s1','n5_s1']:
    w,h,P,S = load(t)
    print(f"== {t} ({w}x{h})")
    # test translations
    trans = []
    for dy in range(h):
        for dx in range(w):
            if dx==0 and dy==0: continue
            ok = all(P[y*w+x]==P[((y+dy)%h)*w+(x+dx)%w] for y in range(h) for x in range(w))
            if ok: trans.append((dx,dy))
    print("  prod translations:", trans[:10])
    # test point symmetries: rotation by 180 about center
    def rot180s(M):
        return all(M[y*w+x]==M[(h-1-y)*w+(w-1-x)] for y in range(h) for x in range(w))
    print("  rot180:", rot180s(P), rot180s(S))
EOF

